<?php
namespace ETG\DynamicFilterSEOBridge\Admin;
use ETG\DynamicFilterSEOBridge\Config\Configuration;use ETG\DynamicFilterSEOBridge\Runtime\ReleaseIdentity;
final class MaintenancePage{
	private $config;private $identity;public function __construct(Configuration $config,ReleaseIdentity $identity){$this->config=$config;$this->identity=$identity;}public function register():void{add_action('admin_menu',array($this,'menu'));add_action('admin_post_etg_dfsb_upgrade_package',array($this,'upgradePackage'));}public function menu():void{add_options_page('ETG SEO Maintenance','ETG SEO Maintenance','manage_options','etg-filter-seo-maintenance',array($this,'render'));}
	public function render():void{if(!current_user_can('manage_options')){return;}$tabs=array('build'=>'Installed Build','upgrade'=>'Package Upgrade');$tab=isset($_GET['tab'])?sanitize_key((string)wp_unslash($_GET['tab'])):'build';if(!isset($tabs[$tab])){$tab='build';}$report=$this->identity->report();$notice=isset($_GET['etg_upgrade_notice'])?sanitize_key((string)wp_unslash($_GET['etg_upgrade_notice'])):'';echo '<div class="wrap"><h1>ETG SEO Maintenance</h1>';if($notice){echo '<div class="notice '.('upgrade_success'===$notice?'notice-success':'notice-error').' inline"><p>'.esc_html($this->notice($notice)).'</p></div>';}echo '<nav class="nav-tab-wrapper">';foreach($tabs as $slug=>$label){$url=add_query_arg(array('page'=>'etg-filter-seo-maintenance','tab'=>$slug),admin_url('options-general.php'));echo '<a class="nav-tab '.($tab===$slug?'nav-tab-active':'').'" href="'.esc_url($url).'">'.esc_html($label).'</a>';}echo '</nav>';if('upgrade'===$tab){$this->renderUpgrade($report);}else{$this->renderBuild($report);}echo '</div>';}
	private function renderBuild(array $report):void{echo '<div class="card" style="max-width:900px;margin-top:20px"><h2>Running package identity</h2><table class="widefat striped"><tbody>';foreach(array('plugin_version'=>'Version','plugin_basename'=>'Plugin basename','git_sha'=>'Git SHA','tree_sha'=>'Tree SHA','source_manifest_sha256'=>'Source manifest SHA256','identity_contract'=>'Identity contract') as $key=>$label){echo '<tr><th>'.esc_html($label).'</th><td><code>'.esc_html((string)($report[$key]??'')).'</code></td></tr>';}echo '</tbody></table><p><strong>Build identity:</strong> '.(!empty($report['build_identity_available'])?'VERIFIED PACKAGE METADATA':'SOURCE/LEGACY INSTALL — PACKAGE METADATA UNAVAILABLE').'</p></div>';}
	private function renderUpgrade(array $report):void{echo '<div class="card" style="max-width:900px;margin-top:20px"><h2>Governed package upgrade</h2><p><strong>Preferred path:</strong> WordPress Plugins → Add Plugin → Upload. If WordPress says “This plugin is already installed” and shows <strong>Replace current with uploaded</strong>, that is the correct upgrade flow and confirms stable plugin identity.</p><p>This maintenance fallback is only for a host where the standard replacement action is unavailable.</p><p><strong>Safety:</strong> Global Bridge must be OFF. The ZIP must have one ETG root, exact plugin identity, bounded archive size, a newer version, and a matching SHA256.</p>';if($this->config->enabled()){echo '<div class="notice notice-error inline"><p>Upgrade is locked while Global Bridge is ON.</p></div></div>';return;}echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="etg_dfsb_upgrade_package"/>';wp_nonce_field('etg_dfsb_upgrade_package');echo '<table class="form-table"><tr><th>Plugin ZIP</th><td><input type="file" name="etg_package" accept=".zip,application/zip" required/></td></tr><tr><th>Expected SHA256</th><td><input class="regular-text code" name="expected_sha256" minlength="64" maxlength="64" pattern="[A-Fa-f0-9]{64}" required/></td></tr></table><p><button class="button button-primary">Validate and Replace Current Package</button></p></form></div>';}
	public function upgradePackage():void{if(!current_user_can('manage_options')||!current_user_can('upload_plugins')){wp_die('Forbidden','Forbidden',array('response'=>403));}check_admin_referer('etg_dfsb_upgrade_package');if($this->config->enabled()){$this->redirect('upgrade_blocked_global_on');}if(empty($_FILES['etg_package'])||!is_array($_FILES['etg_package'])){$this->redirect('upgrade_file_missing');}$expected=strtolower(trim((string)wp_unslash($_POST['expected_sha256']??'')));if(!preg_match('/^[a-f0-9]{64}$/',$expected)){$this->redirect('upgrade_checksum_invalid');}require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/plugin.php';require_once ABSPATH.'wp-admin/includes/class-wp-upgrader.php';require_once ABSPATH.'wp-admin/includes/class-plugin-upgrader.php';require_once ABSPATH.'wp-admin/includes/class-automatic-upgrader-skin.php';require_once ABSPATH.'wp-admin/includes/class-file-upload-upgrader.php';$fileUpload=new \File_Upload_Upgrader('etg_package','package');$package=$fileUpload->package;if(!is_string($package)||!is_readable($package)){$fileUpload->cleanup();$this->redirect('upgrade_file_missing');}$actual=hash_file('sha256',$package);if(!is_string($actual)||!hash_equals($expected,strtolower($actual))){$fileUpload->cleanup();$this->redirect('upgrade_checksum_mismatch');}$inspection=$this->inspectPackage($package);if(is_wp_error($inspection)){$fileUpload->cleanup();$this->redirect('upgrade_package_invalid');}$newVersion=(string)$inspection['Version'];if(version_compare($newVersion,defined('ETG_DFSB_VERSION')?ETG_DFSB_VERSION:'0','<=')){$fileUpload->cleanup();$this->redirect('upgrade_not_newer');}$skin=new \Automatic_Upgrader_Skin();$upgrader=new \Plugin_Upgrader($skin);$result=$upgrader->install($package,array('overwrite_package'=>'update-plugin','clear_update_cache'=>true));$fileUpload->cleanup();if(is_wp_error($result)||!$result){$this->redirect('upgrade_failed');}$this->redirect('upgrade_success');}
	private function inspectPackage(string $package){if(!class_exists('ZipArchive')){return new \WP_Error('ziparchive_unavailable');}$zip=new \ZipArchive();if(true!==$zip->open($package)){return new \WP_Error('zip_open_failed');}$entries=$zip->numFiles;if($entries<1||$entries>2000){$zip->close();return new \WP_Error('zip_entry_limit');}$total=0;$root='etg-dynamic-filter-seo-bridge/';for($i=0;$i<$entries;$i++){$stat=$zip->statIndex($i);$name=is_array($stat)?(string)($stat['name']??''):'';$size=is_array($stat)?(int)($stat['size']??0):0;$total+=$size;if($total>50*1024*1024||''===$name||0!==strpos($name,$root)||false!==strpos($name,'../')||0===strpos($name,'/')||preg_match('#^[A-Za-z]:#',$name)){$zip->close();return new \WP_Error('zip_structure_invalid');}}$main=$zip->getFromName($root.'etg-dynamic-filter-seo-bridge.php');$zip->close();if(!is_string($main)){return new \WP_Error('main_file_missing');}$tmp=wp_tempnam('etg-main.php');if(!$tmp||false===file_put_contents($tmp,$main)){return new \WP_Error('temp_file_failed');}$data=get_plugin_data($tmp,false,false);@unlink($tmp);if((string)($data['Name']??'')!=='ETG Dynamic Filter SEO Bridge'||empty($data['Version'])){return new \WP_Error('plugin_identity_mismatch');}return $data;}
	private function redirect(string $notice):void{$url=add_query_arg(array('page'=>'etg-filter-seo-maintenance','tab'=>'upgrade','etg_upgrade_notice'=>$notice),admin_url('options-general.php'));wp_safe_redirect($url);exit;}private function notice(string $notice):string{$map=array('upgrade_success'=>'Package replaced successfully. Reload this page to confirm the new running build identity.','upgrade_blocked_global_on'=>'Upgrade blocked: Global Bridge must be OFF.','upgrade_file_missing'=>'No readable ZIP was received.','upgrade_checksum_invalid'=>'Expected SHA256 must be exactly 64 hexadecimal characters.','upgrade_checksum_mismatch'=>'Uploaded ZIP SHA256 does not match the expected checksum.','upgrade_package_invalid'=>'Uploaded ZIP failed ETG identity or archive-structure validation.','upgrade_not_newer'=>'Uploaded package version is not newer than the running version.','upgrade_failed'=>'WordPress could not replace the current plugin package.');return (string)($map[$notice]??$notice);}
}
